  <script>
    const navToggle = document.querySelector(".nav-toggle");
    const navLinks = document.querySelector("#primary-links");
    const cartCount = document.querySelector(".cart-count");
    const cartStatus = document.querySelector("#cart-status");
    const addButtons = document.querySelectorAll(".add-to-cart");
    const signupForm = document.querySelector(".signup-form");
    const emailInput = document.querySelector("#email");
    const formStatus = document.querySelector("#form-status");

    let itemsInCart = 0;

    navToggle.addEventListener("click", () => {
      const isOpen = navToggle.getAttribute("aria-expanded") === "true";
      navToggle.setAttribute("aria-expanded", String(!isOpen));
      navLinks.classList.toggle("is-open", !isOpen);
    });

    navLinks.addEventListener("click", (event) => {
      if (event.target instanceof HTMLAnchorElement && navLinks.classList.contains("is-open")) {
        navToggle.setAttribute("aria-expanded", "false");
        navLinks.classList.remove("is-open");
      }
    });

    addButtons.forEach((button) => {
      button.addEventListener("click", () => {
        itemsInCart += 1;
        const product = button.dataset.product;
        cartCount.textContent = String(itemsInCart);
        cartStatus.textContent = `${product} added to cart. ${itemsInCart} ${itemsInCart === 1 ? "item" : "items"} in cart.`;
      });
    });

    signupForm.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!emailInput.validity.valid) {
        emailInput.setAttribute("aria-invalid", "true");
        formStatus.textContent = "Enter a valid email address to join the list.";
        emailInput.focus();
        return;
      }

      emailInput.removeAttribute("aria-invalid");
      formStatus.textContent = "You're on the list. Watch for the next private drop.";
      signupForm.reset();
    });
  </script>
