const path = require('path');
const { chromium } = require('playwright');
const axe = require('axe-core');

(async () => {
  const browser = await chromium.launch();
  const results = [];
  for (const viewport of [{ width: 1366, height: 900 }, { width: 320, height: 900 }]) {
    const page = await browser.newPage({ viewport });
    await page.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });
    await page.addScriptTag({ content: axe.source });
    const result = await page.evaluate(async () => await window.axe.run());
    const wcag = result.violations.filter((v) => !v.tags.includes('best-practice'));
    const bestPractice = result.violations.filter((v) => v.tags.includes('best-practice'));
    results.push({ viewport, wcag, bestPractice });

    if (viewport.width === 320) {
      await page.getByRole('button', { name: 'Menu' }).click();
      const expanded = await page.getByRole('button', { name: 'Menu' }).getAttribute('aria-expanded');
      if (expanded !== 'true') throw new Error('Menu button did not expose expanded state.');
    }

    await page.getByRole('button', { name: 'Join the list' }).click();
    const invalid = await page.locator('#email').getAttribute('aria-invalid');
    const status = await page.locator('#form-status').textContent();
    if (invalid !== 'true' || !status.includes('valid email address')) throw new Error('Email error state was not exposed.');
    await page.close();
  }
  await browser.close();

  const report = results.map(({ viewport, wcag, bestPractice }) => ({
    viewport,
    wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
    best_practice: bestPractice.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))
  }));
  console.log(JSON.stringify(report, null, 2));
  process.exit(results.some((r) => r.wcag.length) ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(1);
});
